</style>
</head>
<body>
<canvas id="stage"></canvas>
<div id="countdown" aria-hidden="true">3</div>

<div id="dock" role="toolbar" aria-label="Simulation Controls">
  <button id="btn-refire" type="button" aria-label="Re-fire" title="Re-fire">
    <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
      <path d="M21.5 2v6h-6M21.34 15.57a10 10 0 1 1-.57-8.38l5.67-5.19"/>
    </svg>
    <span>Re-fire</span>
  </button>
  <span class="dock-sep" aria-hidden="true"></span>
  <button id="btn-toggle" type="button" aria-label="Pause" title="Play / Pause">
    <svg id="icon-pause" viewBox="0 0 24 24" width="14" height="14" fill="currentColor" aria-hidden="true">
      <rect x="6" y="4" width="4" height="16" rx="1"/>
      <rect x="14" y="4" width="4" height="16" rx="1"/>
    </svg>
    <svg id="icon-play" viewBox="0 0 24 24" width="14" height="14" fill="currentColor" aria-hidden="true" style="display:none;">
      <path d="M8 5v14l11-7z"/>
    </svg>
  </button>
  <span class="dock-sep" aria-hidden="true"></span>
  <div id="speed-group" role="radiogroup" aria-label="Playback Speed">
    <button class="speed-pill" type="button" role="radio" aria-checked="false" data-speed="0.25">0.25×</button>
    <button class="speed-pill" type="button" role="radio" aria-checked="false" data-speed="0.5">0.5×</button>
    <button class="speed-pill is-active" type="button" role="radio" aria-checked="true" data-speed="1.0">1.0×</button>
    <button class="speed-pill" type="button" role="radio" aria-checked="false" data-speed="2.0">2.0×</button>
  </div>
  <span class="dock-sep" aria-hidden="true"></span>
  <input id="scrubber" type="range" min="0" max="100" step="0.001" value="0" aria-label="Timeline Scrubber">
</div>
<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
<script id="rampart-strategy">
function createStrategy() {
  return {plan() { return []; }};
}
</script>
<script id="rampart-sim">
function rampartSimulate(createStrategy, seed, maxTicks) {
  const recording = arguments[3];
  const strategy = createStrategy();
  const floor = Math.floor;
  const ground = [[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]];
  const sky = [[0,6],[21,6],[21,11],[23,11]];
  const slots = [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],
    [14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]]
    .map(([x,y]) => ({x, y, cx:x*100+50, cy:y*100+50, turret:null}));
  const guns = [
    ["bolt",50,26,8,300,0,0,0,3], ["cannon",90,60,24,260,90,0,0,1],
    ["frost",70,10,12,240,0,30,0,3], ["lance",120,180,36,360,0,0,1,1],
    ["flak",80,40,10,320,70,0,0,2]
  ].map(([name,cost,damage,period,range,splash,slow,pierce,domain], index) => ({
    name,cost,damage,period,range,splash,slow,pierce,domain,index
  }));
  const gunByName = new Map(guns.map(g => [g.name,g]));
  const species = [
    ["grunt",60,10,4,1,0,1,10], ["runner",40,20,4,1,0,2,4],
    ["wisp",50,12,6,2,1,3,3], ["brute",150,6,9,3,0,4,3],
    ["splitter",90,8,6,2,0,6,2], ["mender",70,8,7,2,0,8,1],
    ["splitling",0,12,1,1,0,Infinity,0]
  ].map(([name,hp,speed,bounty,leak,air,first,weight], index) => ({
    name,hp,speed,bounty,leak,air,first,weight,index
  }));

  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a ''^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ''^ (t >>> 7), 61 | t)) ''^ t; return (t ''^ (t >>> 14)) >>> 0;
  }; }
  const draw = mulberry32(seed);
  function composition(wave) {
    const available = species.filter(type => type.first <= wave);
    const total = available.reduce((sum,type) => sum + type.weight, 0);
    return Array.from({length:4+floor(3*wave/5)}, () => {
      let r = draw() % total;
      for (const type of available) {
        if (r < type.weight) return type;
        r -= type.weight;
      }
    });
  }
  function route(points) {
    const positions = [];
    for (let i = 1; i < points.length; i++) {
      const [x,y] = points[i-1], [toX,toY] = points[i];
      const dx = Math.sign(toX-x), dy = Math.sign(toY-y);
      for (let step = 0; step < 100*(Math.abs(toX-x)+Math.abs(toY-y)); step++) {
        positions.push([x*100+50+step*dx,y*100+50+step*dy,dx,dy]);
      }
    }
    return positions;
  }
  const routes = [route(ground),route(sky)];
  const living = [], queue = [], log = [], scales = [0,1000];
  let tick = 0, gold = 250, baseHp = 10, wave = 0, nextId = 1, fallTick = -1;
  let upcoming = composition(1);
  let preview = [];
  let turretFrame = [];
  const events = recording ? [] : null;
  const frames = recording ? [] : null;
  const addEvent = (kind, data) => events.push({tick,kind,...data});
  if (recording) Object.assign(recording, {
    frames,events,ground,sky,slots:slots.map(({x,y}) => [x,y]),
    enemyNames:species.map(s => s.name), gunNames:guns.map(g => g.name)
  });

  function enemyView(e) {
    return {id:e.id,type:e.kind.name,hp:e.hp,maxHp:e.maxHp,x:e.x,y:e.y,air:e.kind.air,
      armor:e.armor,speed:e.kind.speed,slowed:e.slow,remaining:e.path.length-e.progress};
  }
  function spawn(kind, ownWave, progress, hp) {
    const path = routes[kind.air];
    const [x,y] = path[progress];
    const maxHp = hp ?? floor(kind.hp * scales[ownWave] / 1000);
    const armor = kind.index === 0 ? floor(ownWave/4) : kind.index === 3 ? 6+ownWave : 0;
    living.push({id:nextId++,kind,wave:ownWave,progress,path,x,y,maxHp,hp:maxHp,armor,slow:0,age:0});
  }
  function inRange(ax,ay,bx,by,radius2) {
    const dx = ax-bx, dy = ay-by;
    return dx*dx+dy*dy <= radius2;
  }
  function canHit(gun,e) {
    return gun.domain & (1 << e.kind.air);
  }
  function waveStart() {
    wave++;
    gold += Math.min(50,floor(gold*5/100)) + 10 + 2*wave;
    if (wave > 1) scales[wave] = floor(scales[wave-1]*108/100);
    const spawning = upcoming;
    upcoming = composition(wave+1);
    preview = upcoming.map(kind => kind.name);
    if (events) addEvent("wave",{wave,x:12,z:7});
    const actions = strategy.plan({
      tick,wave,gold,baseHp,
      slots:slots.map(({x,y,turret},slot) => ({
        slot,x,y,turret:turret && {type:turret.gun.name,tier:turret.tier,spent:turret.spent}
      })),
      enemies:living.map(enemyView),nextWave:preview.slice()
    });
    if (Array.isArray(actions)) {
      for (const action of actions.slice(0,32)) {
        if (!action || !Number.isInteger(action.slot) || !slots[action.slot]) continue;
        const i = action.slot, slot = slots[i], turret = slot.turret;
        let code, value;
        if (action.op === "build" && !turret) {
          const gun = gunByName.get(action.type);
          if (!gun || gold < gun.cost) continue;
          gold -= gun.cost;
          slot.turret = {gun,tier:1,spent:gun.cost,damage:gun.damage,range:gun.range,cooldown:0};
          code = "B"; value = gun.index;
        } else if (action.op === "upgrade" && turret && turret.tier < 3) {
          const cost = turret.gun.cost * turret.tier;
          if (gold < cost) continue;
          gold -= cost;
          turret.spent += cost;
          turret.damage = floor(turret.damage*16/10);
          turret.range += 30;
          code = "U"; value = ++turret.tier;
        } else if (action.op === "sell" && turret) {
          gold += floor(turret.spent*70/100);
          slot.turret = null;
          code = "S"; value = 0;
        }
        if (code) {
          log.push([tick,code,i,value]);
          if (events) addEvent(code,{slot:i,x:slot.cx/100,z:slot.cy/100,
            type:(slot.turret || turret).gun.index,tier:(slot.turret || turret).tier});
        }
      }
    }
    if (frames) turretFrame = slots.map(s => s.turret && {type:s.turret.gun.index,tier:s.turret.tier});
    for (let i = 0; i < spawning.length; i++) queue.push({at:tick+4*i,wave,i,kind:spawning[i]});
    queue.sort((a,b) => a.at-b.at || a.wave-b.wave || a.i-b.i);
  }
  function snapshot() {
    if (!frames) return;
    frames.push({wave,gold,baseHp,preview,turrets:turretFrame,enemies:living.map(e => {
      const [, , dx,dz] = e.path[e.progress];
      return {id:e.id,type:e.kind.index,x:e.x/100,z:e.y/100,air:e.kind.air,hp:e.hp,maxHp:e.maxHp,
        slow:e.slow,dx,dz};
    })});
  }

  for (; tick < maxTicks; tick++) {
    if (tick >= 20 && (tick-20)%40 === 0) waveStart();
    while (queue.length && queue[0].at === tick) {
      const next = queue.shift();
      spawn(next.kind,next.wave,0);
    }
    for (let i = 0; i < living.length; i++) {
      const e = living[i];
      const speed = e.kind.speed;
      const progress = e.progress + (e.slow > 0 ? floor(speed*60/100) : speed);
      if (progress >= e.path.length) {
        living.splice(i--,1);
        const before = baseHp;
        baseHp -= e.kind.leak;
        log.push([tick,"L",e.id,baseHp]);
        if (events) addEvent("leak",{x:23.5,z:11.5,before,after:baseHp,id:e.id});
        if (baseHp <= 0) {
          fallTick = tick;
          log.push([tick,"F",wave,0]);
          if (events) addEvent("fall",{x:23.5,z:11.5});
          break;
        }
      } else {
        e.progress = progress;
        [e.x,e.y] = e.path[progress];
      }
    }
    if (fallTick !== -1) { snapshot(); break; }

    for (const e of living) {
      e.age++;
      if (e.kind.name !== "mender" || e.age%20 !== 0) continue;
      for (const other of living) {
        if (inRange(e.x,e.y,other.x,other.y,22500)) {
          other.hp = Math.min(other.maxHp,other.hp+floor(other.maxHp*8/100));
        }
      }
      if (events) addEvent("heal",{x:e.x/100,z:e.y/100});
    }

    for (let i = 0; i < slots.length; i++) {
      const slot = slots[i], turret = slot.turret;
      if (!turret || (turret.cooldown > 0 && --turret.cooldown > 0)) continue;
      const gun = turret.gun, range2 = turret.range*turret.range;
      const candidates = living.filter(e => canHit(gun,e) && inRange(slot.cx,slot.cy,e.x,e.y,range2));
      if (!candidates.length) continue;
      let picked;
      if (strategy.target) {
        const id = strategy.target({slot:i,type:gun.name,tier:turret.tier,x:slot.cx,y:slot.cy,
          range:turret.range},candidates.map(enemyView));
        picked = candidates.find(e => e.id === id);
      }
      if (!picked) {
        picked = candidates.reduce((a,b) => b.path.length-b.progress < a.path.length-a.progress ? b : a);
      }
      if (events) addEvent("shot",{x:slot.cx/100,z:slot.cy/100,slot:i,type:gun.index,tier:turret.tier,
        tx:picked.x/100,tz:picked.y/100,air:picked.kind.air,splash:gun.splash/100});
      const hits = gun.splash ? living.filter(e => canHit(gun,e) &&
        inRange(picked.x,picked.y,e.x,e.y,gun.splash*gun.splash)) : [picked];
      turret.cooldown = gun.period;
      for (const e of hits) {
        e.hp -= Math.max(1,turret.damage-(gun.pierce ? 0 : e.armor));
        if (gun.slow) e.slow = gun.slow;
      }
      for (const e of hits) {
        if (e.hp > 0) continue;
        living.splice(living.indexOf(e),1);
        gold += e.kind.bounty;
        log.push([tick,"K",e.id,i]);
        if (events) addEvent("kill",{x:e.x/100,z:e.y/100,air:e.kind.air,type:e.kind.index,id:e.id});
        if (e.kind.name === "splitter") {
          const hp = Math.max(1,floor(e.maxHp/4));
          for (let j = 0; j < 3; j++) spawn(species[6],e.wave,e.progress,hp);
        }
      }
    }
    for (const e of living) if (e.slow > 0) e.slow--;
    snapshot();
  }
  const score = Math.round(((fallTick === -1 ? maxTicks : fallTick)-20)*2.5)/100;
  let hash = 0x811c9dc5;
  const serialized = JSON.stringify(log);
  for (let i = 0; i < serialized.length; i++) {
    hash = Math.imul(hash ''^ serialized.charCodeAt(i),0x01000193);
  }
  return {score,fallTick,log,hash:(hash>>>0).toString(16).padStart(8,"0")};
}
</script>
EOF
TEST_DIR=$(mktemp -d)
echo "$TEST_DIR" > "$TMPDIR/rampart-test-dir"
python3 - "$TEST_DIR" <<'"'PY'
import sys
from pathlib import Path
t=Path('index.html').read_text()
Path(sys.argv[1],'sim.js').write_text(t.split('<script id=\"rampart-sim\">')[1].split('</script>')[0])
PY
cat > \""'$TEST_DIR/vectors.js" <<'"'EOF'
const a = () => ({plan(s) { const a = []; let g = s.gold; for (const sl of s.slots) if ("'!sl.turret && g >= 50) { a.push({op:"build",slot:sl.slot,type:"bolt"}); g -= 50; } return a; }});
const b = () => ({plan(s) { return ({
  1:[{op:"build",slot:3,type:"cannon"},{op:"build",slot:6,type:"frost"}],
  3:[{op:"upgrade",slot:3},{op:"build",slot:12,type:"flak"}],
  6:[{op:"build",slot:8,type:"lance"},{op:"sell",slot:6}]
})[s.wave] || []; }});
for (const [f,seed] of [[a,42],[b,7]]) {
  const result = rampartSimulate(f,seed,12020);
  print(result.score,result.fallTick,result.log.length,result.hash,JSON.stringify(result.log.slice(0,6)));
}
EOF
/System/Library/Frameworks/JavaScriptCore.framework/Versions/A/Helpers/jsc "$TEST_DIR/sim.js" "$TEST_DIR/vectors.js"'

