  const guns = [
    ["bolt",50,26,8,300,0,0,0,3], ["cannon",90,60,24,260,90,0,0,1],
    ["frost",70,10,12,240,0,30,0,3], ["lance",120,180,36,360,0,0,1,1],
    ["flak",80,40,10,320,70,0,0,2]
  ].map(([name,cost,damage,period,range,splash,slow,pierce,domain], index) => ({
    name,cost,damage,period,range,splash,slow,pierce,domain,index
  }));
  const gunByName = new Map(guns.map(g => [g.name,g]));
  const species = [
    ["grunt",60,10,4,1,0,1,10], ["runner",40,20,4,1,0,2,4],
    ["wisp",50,12,6,2,1,3,3], ["brute",150,6,9,3,0,4,3],
    ["splitter",90,8,6,2,0,6,2], ["mender",70,8,7,2,0,8,1],
    ["splitling",0,12,1,1,0,Infinity,0]
