    a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a ''^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ''^ (t >>> 7), 61 | t)) ''^ t; return (t ''^ (t >>> 14)) >>> 0;
  }; }
  const draw = mulberry32(seed);
  function composition(wave) {
    const available = species.filter(type => type.first <= wave);
    const total = available.reduce((sum,type) => sum + type.weight, 0);
    return Array.from({length:4+floor(3*wave/5)}, () => {
      let r = draw() % total;
      for (const type of available) {
        if (r < type.weight) return type;
        r -= type.weight;
      }
    });
  }
  function route(points) {
    const positions = [];
    for (let i = 1; i < points.length; i++) {
      const [x,y] = points[i-1], [toX,toY] = points[i];
      const dx = Math.sign(toX-x), dy = Math.sign(toY-y);
      for (let step = 0; step < 100*(Math.abs(toX-x)+Math.abs(toY-y)); step++) {
        positions.push([x*100+50+step*dx,y*100+50+step*dy,dx,dy]);
      }
    }
    return positions;
