  const living = [], queue = [], log = [], scales = [0,1000];
  let tick = 0, gold = 250, baseHp = 10, wave = 0, nextId = 1, fallTick = -1;
  let upcoming = composition(1);
  let preview = [];
  let turretFrame = [];
  const events = recording ? [] : null;
  const frames = recording ? [] : null;
  const addEvent = (kind, data) => events.push({tick,kind,...data});
