      })),
      enemies:living.map(enemyView),nextWave:preview.slice()
    });
    if (Array.isArray(actions)) {
      for (const action of actions.slice(0,32)) {
        if (!action || !Number.isInteger(action.slot) || !slots[action.slot]) continue;
        const i = action.slot, slot = slots[i], turret = slot.turret;
        let code, value;
        if (action.op === "build" && !turret) {
          const gun = gunByName.get(action.type);
          if (!gun || gold < gun.cost) continue;
          gold -= gun.cost;
          slot.turret = {gun,tier:1,spent:gun.cost,damage:gun.damage,range:gun.range,cooldown:0};
