        const id = strategy.target({slot:i,type:gun.name,tier:turret.tier,x:slot.cx,y:slot.cy,
          range:turret.range},candidates.map(enemyView));
        picked = candidates.find(e => e.id === id);
      }
      if (!picked) {
        picked = candidates.reduce((a,b) => b.path.length-b.progress < a.path.length-a.progress ? b : a);
      }
      if (events) addEvent("shot",{x:slot.cx/100,z:slot.cy/100,slot:i,type:gun.index,tier:turret.tier,
