        if (e.hp > 0) continue;
        living.splice(living.indexOf(e),1);
        gold += e.kind.bounty;
        log.push([tick,"K",e.id,i]);
        if (events) addEvent("kill",{x:e.x/100,z:e.y/100,air:e.kind.air,type:e.kind.index,id:e.id});
