  // Slot priority, final turret, and the priority of buying its two tiers.
  const layout = [
    [0,\"cannon\",5,17,28],
    [2,\"cannon\",7,19,17],
    [1,\"bolt\",12,25,53],
    [15,\"flak\",4,10,29],
    [5,\"flak\",-8,26,37],
    [3,\"cannon\",7,14,26],
    [6,\"cannon\",14,20,46],
    [7,\"cannon\",39,33,23],
    [8,\"cannon\",7,22,44],
    [4,\"cannon\",2,24,37],
    [11,\"cannon\",15,26,37],
    [12,\"flak\",41,23,45],
    [10,\"bolt\",13,50,32],
    [9,\"cannon\",7,52,52],
    [13,\"bolt\",8,49,60],
    [14,\"frost\",9,50,61]
  ];
  const costs = {bolt:50,cannon:90,frost:70,lance:120,flak:80};
  const damage = {bolt:[26,41,65],cannon:[60,96,153],frost:[10,16,25],
    lance:[180,288,460],flak:[40,64,102]};
  const tuning = [0.6,0.3158,1.1336,0.2,0.6,0.0617,0.4723,0.5899,0.4258,0.35,0.8,0.2,4,10,0.3];

  function plan(state) {
    const {wave,slots,nextWave,enemies} = state;
    let gold = state.gold;
    const actions = [];
    const tiers = slots.map(s => s.turret ? s.turret.tier : 0);
    const flyers = nextWave.filter(name => name === \"wisp\").length;
    const airPressure = Math.min(3,flyers) + enemies.filter(e => e.air && e.remaining < 1050).length * 0.5;
    for (const [slot,type,when] of [[0,\"cannon\",1],[2,\"cannon\",1],[1,\"bolt\",1]]) {
      if (wave "'!== when) continue;
      gold -= costs[type];
      tiers[slot] = 1;
      actions.push({op:"build",slot,type});
    }
    const reserve = wave < 5 ? 0 : wave < 18 ? (wave-4)*tuning[12] : Math.max(0,(29-wave)*tuning[13]);
    for (let i = 0; i < 28; i++) {
      let choice, best = Infinity;
      for (const [slot,type,...order] of layout) {
        const tier = tiers[slot];
        if (tier === 3 || (type === "flak" && wave < 3)) continue;
        const priority = order[tier] - (type === "flak" ? airPressure*tuning[14] : 0);
        if (priority < best) {
          best = priority;
          choice = {slot,type,tier,cost:costs[type]*Math.max(1,tier)};
        }
      }
      if (!choice || gold < choice.cost+reserve) break;
      const {slot,type,tier,cost} = choice;
      tiers[slot]++;
      actions.push(tier ? {op:"upgrade",slot} : {op:"build",slot,type});
      gold -= cost;
    }
    return actions;
  }

  function target(turret, candidates) {
    const {type,tier,range,x,y} = turret;
    const raw = damage[type][tier-1];
    const radius = type === "cannon" ? 8100 : type === "flak" ? 4900 : 0;
    let best = -Infinity, id = candidates[0].id;
    function value(e) {
      const hit = Math.max(1,raw-(type === "lance" ? 0 : e.armor));
      const timeLeft = e.remaining/e.speed;
      const urgency = 1 + tuning[0]*Math.max(0,1-timeLeft/180) + tuning[1]*Math.max(0,1-timeLeft/60);
      const priority = 1 + (e.type === "mender" ? tuning[2] : 0) +
        (e.type === "brute" ? tuning[3] : 0) + (e.air ? tuning[11] : 0);
      const usefulDamage = Math.min(e.hp,hit)/raw;
      const finish = e.hp <= hit ? tuning[4] : tuning[5]*hit/e.hp;
      return priority*urgency*(usefulDamage+finish);
    }
    const values = candidates.map(value);
    for (let i = 0; i < candidates.length; i++) {
      const e = candidates[i];
      const dx = e.x-x, dy = e.y-y;
      let weight = values[i];
      if (radius) {
        for (let j = 0; j < candidates.length; j++) {
          if (j === i) continue;
          const n = candidates[j], ax = e.x-n.x, ay = e.y-n.y;
          if (ax*ax+ay*ay <= radius) weight += values[j]*tuning[6];
        }
        weight += tuning[7]*Math.max(0,1-e.remaining/e.speed/90);
      }
      if (type === "frost") {
        weight += (1-Math.min(30,e.slowed)/30)*tuning[8]*
          (1+tuning[9]*Math.max(0,1-e.remaining/e.speed/95));
      }
      weight += tuning[10]*(dx*dx+dy*dy)/(range*range) * Math.max(0,1-e.remaining/e.speed/160);
      if (weight > best) { best = weight; id = e.id; }
    }
    return id;
  }
  return {plan,target};
}'"'"

