const replacement = () => [pick([7,9,10,11,12,13,14]),35+rnd(10),pick(["cannon","lance","frost","flak","bolt"]),rnd(2),100+rnd(1300),190+rnd(440)];
for(let i=0;i<1100;i++) {
  const cfg=JSON.parse(JSON.stringify(pick(pool).cfg));
  for(let j=0;j<1+rnd(4);j++) {
    if(rand()<0.47) {
      const k=rnd(4), caps=[17,280,1.5,6], increments=[3,65,0.5,1.6];
      cfg.target[k]=Math.max(k===1?30:0,Math.min(caps[k],cfg.target[k]+(rand()-0.4)*increments[k]));
    } else if(cfg.swaps.length===0 || (rand()<0.28 && cfg.swaps.length<5)){
      const row=replacement();
      if(!cfg.swaps.some(r=>r[0]===row[0])) cfg.swaps.push(row);
    } else {
      const k=rnd(cfg.swaps.length);
      if(rand()<0.18)cfg.swaps.splice(k,1);
      else{
        const c=1+rnd(5);cfg.swaps[k][c]=replacement()[c];
      }
    }
  }
  const quick=evaluate(cfg,preview);
  if(pool.some(p=>p.quick===quick)) continue;
  if(pool.length<9 || quick>pool.at(-1).quick-0.25) {
   const full=evaluate(cfg,train);
   if(full>best){best=full;print("BEST",i,full,JSON.stringify(cfg));}
   if(full>best-0.8){
     pool.push({cfg,quick,full});
     pool.sort((a,b)=>(b.full*0.8+b.quick*0.2)-(a.full*0.8+a.quick*0.2));
     if(pool.length>10)pool.pop();
   }
  }
}
