async function main(){
 const s=new WebSocket("ws://127.0.0.1:9229/session");
 const listeners=new Map();
 let id=0;
 s.addEventListener("message",ev=>{
   const message=JSON.parse(ev.data);
   if(message.id && listeners.has(message.id)){
     const [resolve,reject]=listeners.get(message.id);listeners.delete(message.id);
     if(message.type==="error") reject(new Error(JSON.stringify(message)));
     else resolve(message.result);
   } else if(message.method==="log.entryAdded") console.log("LOG",JSON.stringify(message.params));
 });
 await new Promise((resolve,reject)=>{s.addEventListener("open",resolve,{once:true});s.addEventListener("error",reject,{once:true});});
 const send=(method,params={})=>new Promise((resolve,reject)=>{
   const i=++id;listeners.set(i,[resolve,reject]);s.send(JSON.stringify({id:i,method,params}));
 });
 console.log(await send("session.new",{capabilities:{alwaysMatch:{acceptInsecureCerts:false}}}));
 await send("session.subscribe",{events:["log.entryAdded"]});
 const tree=await send("browsingContext.getTree",{});
 const context=tree.contexts[0].context;
 console.log("CONTEXT",context);
 await send("browsingContext.setViewport",{context,viewport:{width:1280,height:650},devicePixelRatio:1});
 console.log(await send("browsingContext.navigate",{context,url:pathToFileURL(path.resolve("index.html")).href,wait:"complete"}));
 const evalJS=async (expression,awaitPromise=false)=>{
   let out=await send("script.evaluate",{expression,awaitPromise,target:{context}});
   if(out.type==="exception") throw new Error(JSON.stringify(out));
   return out.result.value;
 };
 const capture=async name=> {
   const out=await send("browsingContext.captureScreenshot",{context});
   fs.writeFileSync(path.resolve("../tmp/rampart-"+name+".png"),Buffer.from(out.data,"base64"));
 };
 console.log(await evalJS("JSON.stringify({report:window.BENCH_REPORT,three:typeof THREE,count:document.querySelectorAll('canvas').length,dimensions:[innerWidth,innerHeight]})"));
 await evalJS("document.getElementById('btn-toggle').click()");
 await capture("rest");
 for (const t of [26,59,82.3,90.8,100]) {
    await evalJS(`(() => {const s=document.getElementById('scrubber');s.value=${t};s.dispatchEvent(new Event('input'));})()`);
    await capture(String(t));
 }
 await send("session.end");
 s.close();
}
main().catch(e=>{console.error(e);process.exit(1);});

